let apiSettingsCache=null,apiBusy=false,apiDraft=null,apiTaskMode='organize',apiInstructions='',apiStatus='';
const apiConversionView=conversionView;
conversionView=function(){return apiConversionView().replace('<span class="panel-title">普通剧本文本</span>','<span class="panel-title">普通剧本文本</span><button class="btn small" data-action="api-jump">API 辅助设计</button>')+`<section class="api-assistant panel"><div class="panel-head"><strong>API 辅助设计</strong><button class="btn small" data-action="api-settings">接口设置</button></div><div class="api-body"><p class="field-note">将上方输入文本、工程角色名和章节名发送到你配置的接口。整理结果先在下方预览，确认后再进入文本识别流程。</p><div class="field-row"><div class="field"><label>辅助方式</label><select id="apiMode" ${apiBusy?'disabled':''}>${optionList({organize:'整理原文（保留正文）',polish:'润色与补充描写',branches:'设计选项与分支'},apiTaskMode)}</select></div><div class="field"><label>当前接口</label><p id="apiProvider">${esc(apiSettingsCache?.model||'尚未设置模型')}</p></div></div><div class="field"><label>补充要求（选填）</label><textarea id="apiInstructions" maxlength="4000" placeholder="例如：保持第一人称，将结局整理成两个分支。">${esc(apiInstructions)}</textarea></div><div class="card-actions"><button class="btn primary" data-action="api-run" ${apiBusy?'disabled':''}>${apiBusy?'正在处理…':'发送文本并生成预览'}</button><button class="btn" data-action="api-cancel" ${apiBusy?'':'disabled'}>取消请求</button><span id="apiStatus" role="status">${esc(apiStatus)}</span></div><div id="apiResult">${apiResultMarkup()}</div></div></section>`};
function apiResultMarkup(){if(!apiDraft||apiDraft.projectId!==project.id)return '';return `<h3>API 建议稿 · ${esc({organize:'整理原文',polish:'润色描写',branches:'设计分支'}[apiDraft.mode])}</h3><p class="field-note">检查角色归属、章节和正文。建议稿可编辑；采用后仍需完成角色、章节和引号对白确认，才会写入工程。</p><textarea id="apiDraftText" aria-label="API 建议稿" class="conversion-text">${esc(apiDraft.text)}</textarea><div class="card-actions"><button class="btn primary" data-action="api-adopt" ${apiBusy?'disabled':''}>采用建议稿并识别</button><button class="btn" data-action="api-discard">丢弃建议稿</button></div>`}
async function openApiSettings(){if(!window.apiAssistant){notify('请在新版桌面工作台中使用 API');return}try{apiSettingsCache=await window.apiAssistant.settings();const s=apiSettingsCache;dialog('API 接口设置',`<p>支持 Chat Completions 格式的服务。填写服务商提供的接口地址和完整模型名。本地模型服务可不填密钥。</p><div class="field"><label>接口地址（基础地址或完整 /chat/completions 地址）</label><input name="endpoint" type="url" required value="${esc(s.endpoint)}" placeholder="https://你的服务地址/v1"></div><div class="field"><label>模型名称</label><input name="model" required maxlength="200" value="${esc(s.model)}" placeholder="填写服务商提供的模型 ID"></div><div class="field"><label>API 密钥${s.hasKey?'（已保存，留空保留）':''}</label><input name="key" type="password" autocomplete="new-password" placeholder="${s.hasKey?'留空保留现有密钥':'本地无认证接口可留空'}"></div><label class="subtitle-check"><input name="remember" type="checkbox" ${s.remember?'checked':''}>在此电脑加密记住密钥</label><label class="subtitle-check"><input name="clearKey" type="checkbox">清除现有密钥</label><p class="field-note">密钥不写入工程，也不随游戏打包。未勾选记住时，仅本次工作台运行期间保留。使用在线接口可能按服务商规则计费。</p>`,'保存设置',async f=>{try{apiSettingsCache=await window.apiAssistant.save({...Object.fromEntries(f),remember:f.has('remember'),clearKey:f.has('clearKey')});notify('接口设置已保存');draw()}catch(e){notify('保存失败：'+e.message)}});$('#dialogForm .actions').insertAdjacentHTML('afterbegin','<button type="button" class="btn" data-action="api-test">保存并测试连接</button>')}catch(e){notify(e.message)}}
async function runApiAssistant(test=false){if(apiBusy)return;if(!window.apiAssistant){notify('请在新版桌面工作台中使用 API');return}if(!test){apiTaskMode=$('#apiMode')?.value||apiTaskMode;apiInstructions=$('#apiInstructions')?.value||'';conversionSource=$('#conversionSource')?.value||conversionSource;if(!conversionSource.trim()){notify('请先粘贴或输入剧本文本');return}}const capture={projectId:project.id,source:conversionSource,mode:apiTaskMode,characters:project.characters.map(c=>c.name),chapters:project.scenes.map(s=>s.name)};apiBusy=true;apiStatus=test?'正在测试连接…':'正在请求接口…';draw();try{apiSettingsCache=await window.apiAssistant.settings();const result=await window.apiAssistant.run(test?{mode:'test'}:{mode:apiTaskMode,source:capture.source,instructions:apiInstructions,characters:capture.characters,chapters:capture.chapters});if(test){apiStatus='连接成功';notify(apiStatus)}else if(project.id!==capture.projectId){apiStatus='工程已切换，本次结果未写入';notify(apiStatus)}else{apiDraft={...capture,text:result.text};apiStatus='建议稿已生成，请审阅';notify(apiStatus)}}catch(e){apiStatus=e.message;notify(apiStatus)}finally{apiBusy=false;draw();if(view==='text')$('.api-assistant')?.scrollIntoView({block:'start'})}}
function adoptApiDraft(){if(!apiDraft||apiDraft.projectId!==project.id)return;const apply=()=>{conversionSource=apiDraft.text;conversionResult=null;conversionParsedSource=null;conversionRoleMap={};conversionSceneMap={};conversionQuoteMap={};conversionChapterPlans=[];view='text';draw();previewConversion();notify('已载入建议稿，请确认角色与章节后再加入剧本')};if(conversionSource!==apiDraft.source)dialog('采用 API 建议稿','<p>输入文本在请求后已修改。采用将替换当前文本输入，原工程剧情不会立即改动。</p>','采用建议稿',apply);else apply()}
document.addEventListener('input',e=>{if(e.target.id==='apiInstructions')apiInstructions=e.target.value;if(e.target.id==='apiDraftText'&&apiDraft)apiDraft.text=e.target.value});
document.addEventListener('change',e=>{if(e.target.id==='apiMode')apiTaskMode=e.target.value});
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(!['api-jump','api-settings','api-run','api-cancel','api-test','api-adopt','api-discard'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();if(a==='api-jump')$('.api-assistant')?.scrollIntoView({behavior:'smooth',block:'start'});if(a==='api-settings')openApiSettings();if(a==='api-run')runApiAssistant();if(a==='api-cancel')window.apiAssistant?.cancel();if(a==='api-adopt')adoptApiDraft();if(a==='api-discard'){apiDraft=null;draw()}if(a==='api-test'){try{const f=new FormData($('#dialogForm'));apiSettingsCache=await window.apiAssistant.save({...Object.fromEntries(f),remember:f.has('remember'),clearKey:f.has('clearKey')});$('#modal').close();runApiAssistant(true)}catch(e){notify(e.message)}}},true);
draw();
